/**
 * Where a provider's page is on everyapp.com: one page per company
 * (`landing-page/content/docs/providers/<company>.mdx`), each with a
 * section per way in (API key, connect accounts, sign in). A catalog
 * entry or OAuth preset maps to its company's page; a provider a Gateway
 * registered from its own spec has none, so it gets the page on custom
 * providers.
 */
import { CAPABILITIES, OAUTH_PRESETS } from "@every-app/sdk/internal";
// The same map the pages are generated by (src/docs/providerPages.ts), so a link never misses its page.
import { COMPANY_OF } from "@/docs/providerGuides";
import { providerCompanies } from "@/docs/providerPages";

const SITE = "https://everyapp.com";

/** The company page `id` is on: `google` for `google-workspace`, `github` for `github-oauth`. */
function providerCompany(id: string): string {
  return COMPANY_OF[id] ?? id.replace(/-oauth$/, "");
}

/** The page to read before setting `id` up: its company's, or the custom-providers page for one the catalog doesn't ship. */
export function providerDocsUrl(id: string): string {
  const shipped = Object.hasOwn(CAPABILITIES, id) || Object.hasOwn(OAUTH_PRESETS, id);
  return `${SITE}/docs/providers/${shipped ? providerCompany(id) : "custom"}`;
}

/**
 * The provider page's numbered "connect accounts" steps for `id`, as plain
 * terminal text, or undefined when its page has generic steps (no guide, or a
 * company with several OAuth clients). The step that mentions the redirect URI
 * gets the URI on its own line, so a terminal never links trailing punctuation.
 */
export function providerConnectSteps(id: string, redirectUri: string): string[] | undefined {
  const company = providerCompanies().find((entry) => entry.clients.some((client) => client.id === id));
  const steps = company?.clients.length === 1 ? company.guide.connect : undefined;
  if (!steps?.length) return undefined;
  return steps.map((step, index) => {
    const text = plainText(step);
    const numbered = `${index + 1}. ${text.replace(/redirect URI above/g, "redirect URI")}`;
    return /redirect URI/.test(text) ? `${numbered}\n   ${redirectUri}` : numbered;
  });
}

/** Markdown to terminal text: `**bold**` and code ticks dropped, links as `text (url)`, or the bare URL when the text is the URL and a space follows. */
export function plainText(markdown: string): string {
  return markdown
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (link: string, text: string, href: string, at: number, whole: string) => {
      const url = href.startsWith("/") ? `${SITE}${href}` : href;
      // Bare only when nothing but a space or the end follows: a terminal would link trailing punctuation.
      const spaced = /^(\s|$)/.test(whole.slice(at + link.length));
      return spaced && url.replace(/^https?:\/\//, "").replace(/\/$/, "") === text.replace(/\/$/, "") ? url : `${text} (${url})`;
    })
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/`([^`]+)`/g, "$1");
}
